                default : break;
            }
            $items_array[] = implode(",", $arr_form_data[$criteria]);
            $items_count_array[] = count($arr_form_data[$criteria]);

            $i++;
        }

        $dataForHistory['criteria'] = implode(",", $criteria_array);
        $dataForHistory['criteria_name'] = implode(",", $criteria_name_array);
        $dataForHistory['items'] = implode(",", $items_array);
        $dataForHistory['items_count'] = implode(",", $items_count_array);


        if ($mode == 'pdf') {
            $dataForHistory['mode'] = 'PDF Download';
        } else if ($mode == 'excel') {
            $dataForHistory['mode'] = 'Excel Download';
        } else {
            $dataForHistory['mode'] = 'View Report';
        }

        $user_id = $this->Session->read('login_user_id');
        $dataForHistory['user_id'] = isset($user_id) ? $user_id : '';
        $user_name = $this->Session->read('user_name');
        $dataForHistory['user_name'] = isset($user_name) ? $user_name : '';

//        debug($dataForHistory);
        $this->ReportAudit->useDbConfig = $this->Session->read('ds');
        $this->ReportAudit->save($dataForHistory);
    }

      public function generatereport($type = '', $mode = '') {
        $this->autoRender = false;
        $company_code = $this->Session->read('company_code');
        // Edited by Akshay on 27-2-2026
        // $specialCompanies = [
        //     'ABSG',
        //     'VGFS',
        //     'VSFS',
        //     'DRRC',
        //     'DJIC',
        //     'AGNG',
        //     'AYRK',
        //     'SHRD',
        //     'RRLC',
        //     'SNRY',
        //     'GTRA',
        //     'SHYD',
        //     'VGNN',
        //     'SRTS'
        // ];
        $specialCompanies = ['HRBL','KWMT','AIMA','ESNP','MBCT','MRBS','STCL','VGNN','ABSG','VGFS','VSFS','DRRC','DJIC','AGNG','AYRK','SRTS','SHYD','GTRA']; // Edited by Akshay on 23-3-2026
        // End
        switch ($type) {
            case 'salary':
                //ctc summary report
                if($company_code=='DEMO' || $company_code=='SRTS'){
                     $this->generatesalaryreportPSQUARE($mode);
                 }
                 else{
                     $this->generatesalaryreport($mode);
                 }
                break;
            case 'salarystructure':
                //ctc detail report
               if($company_code=='DEMO' || $company_code=='GLET' || $company_code=='SRTS'){
                    $this->generateEmpSalaryreportPSQUARE($mode);
                 }
                 else{
                $this->generateEmpSalaryreport($mode);
                 }
                break;
            //ARUN Gross
           case 'Grosssalary':
                //gross salary detail report
                if($company_code=='DEMO' || $company_code=='SRTS'){
                    $this->GenerateSalaryGrossPSQUARE($mode);
                }
                // Edited by Akshay on 26-9-2025
                elseif($company_code == 'KWMT' || $company_code == 'GTRA'){
                  $this->GenerateSalaryGrossKWMT($mode);                    
                }
                // End
                else{
                    // Edited by Akshay on 27-2-2026
                    if (!in_array($company_code, $specialCompanies)) {
                        $this->GenerateSalaryGrossNonExemted($mode);
                    }else{
                        $this->GenerateSalaryGross($mode);
                    }
                    // End
                }
                break;
            case 'SalaryCombined':
                //Salary Combined  report
                 if($company_code=='DEMO' || $company_code=='GLET' || $company_code=='SRTS'){
                    $this->generateSalaryCombinedPSQUARE($mode);
                 }
                 else{
                     $this->generateSalaryCombined($mode);
                 }
                break;
            case 'GrosssalaryNew':
                //gross salary detail report new
                if($company_code=='DEMO' || $company_code=='GLET' || $company_code=='SRTS'){
                    $this->GenerateSalaryGrossNewPSQUARE($mode);
                }
                else{
                    // Edited by Akshay on 27-2-2026
                    if (!in_array($company_code, $specialCompanies)) {
                        $this->GenerateSalaryGrossNewNotExempted($mode);
                    }else{
                        $this->GenerateSalaryGrossNew($mode);
                    }
                    // End
                }
                break;
            case 'SlipFirstVersion':
                //derric slip
                $this->GenerateSalaryslipFirstVersion($mode);
                break;
            case 'SlipSecondVersion':
                //derric slip
                $this->GenerateSalaryslipSecondVersion($mode);
                break;
            case 'SlipThirdVersion':
                //derric slip
                $this->GenerateSalaryslipThirdVersion($mode);
                break;
            case 'GrosssalarySummary':
                //gross salary summary reports
                if($company_code=='DEMO' || $company_code=='GLET' || $company_code=='SRTS'){
                  $this->GenerateSalaryGrossSummaryPSQUARE($mode);
                }
                else{
                    $this->GenerateSalaryGrossSummary($mode);
                }
                break;
            case 'SummaryPayroll':
                //payroll summary report
                if($company_code=='DEMO' || $company_code=='GLET' || $company_code=='SRTS'){
                      $this->GenerateSummaryPayrolreportPSQUARE($mode);
                }
                else{
                $this->GenerateSummaryPayrolreport($mode);
                }
                break;
            case 'Salaryslip':
                //salary slip
                if($company_code=='DEMO'  || $company_code=='SRTS'){
                    $this->GenerateSalarySlipreportPSQUARE($mode);
                 }
                 else if($company_code=='SHYD' || $company_code=='GLET'|| $company_code=='GAAR'){
                    $this->GenerateSalarySlipreportSBL($mode);
                 }
                 else{
                    // Edited by Akshay on 27-2-2026
                    if (!in_array($company_code, $specialCompanies)) {
                        $this->GenerateSalarySlipreport($mode);
                    }else{
                        $this->GenerateSalarySlipreportExempted($mode);
                    }
                    // End
                 }
                break;
            case 'Salaryslipnew':
                //salary slip
                $this->GenerateSalarySlipnewreport($mode);
                break;
            case 'TimeAttendance':
                $this->generatetimeattendancereport($type, $mode);
                break;
            case 'GrossPeriod':
                //salary gross period wise report
                if($company_code=='DEMO' || $company_code=='GLET' || $company_code=='SRTS'){
                     $this->GenerateSalaryGrossPeriodPSQUARE($mode);
                 }
                 else{
                     $this->GenerateSalaryGrossPeriod($mode);
                 }
                break;
            case 'BankTranfer':
                //salary bank transfer report
                if($company_code=='DEMO' || $company_code=='GLET' || $company_code=='SRTS'){
                    $this->generateBanktransferreportPSQUARE($type, $mode);
                 }
                 else{
                $this->generateBanktransferreport($type, $mode);
                 }
                break;
            case 'BankTranferNew':
                //salary bank transfer report
                $this->generateBanktransfernewreport($type, $mode);
                break;
            //added by amal MonthlyCTCReport 3
            case 'MonthlyCTCReport':
                if($company_code=='DEMO' || $company_code=='GLET' || $company_code=='SRTS'){
                    $this->generateEmpMonthlyCTCReportPSQUARE($mode);
                }
                else{
                  $this->generateEmpMonthlyCTCReport($mode);
                }
                break;
            //lop report added by megha  27/05/2020
            case 'LOPREPORT':
                 if($company_code=='HDEQ' || $company_code=='HDFN' || $company_code=='HDSC'||$company_code=='HDCM'||$company_code=='HDGF'){
                    $this->generateLOPReportHEDGE($mode);
                 }else{
                    $this->generateLOPReport($mode);
                 }
                
                break;
            //Edited by Akshay on 2-2-2024
            case 'DepositslipSynthite':
                $this->GenerateDepositSlipreportSynthite($mode);
                break;
            //Edited by Akshay on 8-4-2024
            case 'Comparison':
                if($company_code=='DEMO' || $company_code=='GLET' || $company_code=='SRTS'){
                    $this->GenerateSalaryComparisonPSQUARE($mode);
                 }
                 else{
                   $this->GenerateSalaryComparison($mode);
                 }
                break;
            //Edited by Akshay on 2-7-2024
            case 'BankTranferSynthite':
                $this->generateBanktransfersynthitereport($type, $mode);
                break;
            //Edited by Akshay on 27-5-2024
            case 'Custom':
                $this->generateCustomreport($mode);
                break;
                //End
            // Edited by Athira on 7-1-2025
            case 'SalaryBulkUpload':
                //salary bank transfer report
                $this->generateSalaryBulkUploadreport($type, $mode);
                break;
            //edited by sinsiya on 19-05-2025
            case 'SalaryRevision':
                
                $this->generateSalaryRevision($type, $mode);
                break;
            // End
            // Edited by Akshay on 20-5-2025
            case 'PayrollCTC':    
                $this->generatePayrollCTC($type, $mode);
                break;
            // End
            // Edited by Akshay on 5-1-2026
            case 'Account':
                $this->GenerateSalaryAccountReport($mode);
                break;
            // End
            default:
                return false;
                break;
        }
		$this->downloadHistory($type, $mode);
    }

    public function listemployeefields() {
        App::import('Vendor', 'EmployeeInformationFields', array('file' => 'ReportFields' . DS . 'EmployeeInformationFields.php'));
        $arr_empinformation_fields = new EmployeeInformationFields();
        $arr_emp_field_headings = array_merge(
                $arr_empinformation_fields->getFieldHeadings('EmployeeDetails'), $arr_empinformation_fields->getFieldHeadings('EmployeeProfessionalDetails'), $arr_empinformation_fields->getFieldHeadings('Departments'), $arr_empinformation_fields->getFieldHeadings('Grades'), $arr_empinformation_fields->getFieldHeadings('Verticals'), $arr_empinformation_fields->getFieldHeadings('Units')
        );
        $arr_emp_field_names = array(
            'EmployeeDetails' => $arr_empinformation_fields->getFieldNames('EmployeeDetails'),
            'EmployeeProfessionalDetails' => $arr_empinformation_fields->getFieldNames('EmployeeProfessionalDetails'),
            'Departments' => $arr_empinformation_fields->getFieldNames('Departments'),
            'Grades' => $arr_empinformation_fields->getFieldNames('Grades'),
            'Verticals' => $arr_empinformation_fields->getFieldNames('Verticals'),
            'Units' => $arr_empinformation_fields->getFieldNames('Units')
        );

        $resp_emp = array();
        $resp_emp["rows"] = array();
        foreach ($arr_emp_field_names as $key => $value) {
            foreach ($value as $key1 => $value1) {
                $data['id'] = $key . '.' . $key1;
                $data['data'] = array($value1);
                $resp_emp["rows"][] = $data;
            }
        }
        echo json_encode($resp_emp);
        $this->autoRender = FALSE;
    }

    private function _modelExists($modelName) {
        $models = App::objects('model');
        return in_array($modelName, $models);
    }

    // Edited by Akshay on 5-1-2026
    public function getAccountPeriod()
    {
        $this->autoRender = false;
        $this->response->type('json');
        $this->EmpCtcTransaction->useDbConfig = $this->Session->read('ds');

        $type = $this->request->data('type');

        $result = [];

        if (true) {

            $result['label'] = 'Month';
            $result['options'] = [];

            $start_month = strtotime(date('Y-m', strtotime("+1 month")));

            for ($i = 0; $i < 78; $i++) {
                $month = date('Y-m', strtotime("-$i month", $start_month));
                $monthYear = date('M-Y', strtotime("-$i month", $start_month));
                $result['options'][$month] = $monthYear;
            }
        } else {

            $result['label'] = 'Financial Year';
            $result['options'] = [];

            $arr_fin_year =  $this->EmpCtcTransaction->query("SELECT fin_year,  YEAR(start_month) AS start_year, YEAR(end_month) AS end_year FROM fin_year WHERE vattr1 = 1 AND status = 1 GROUP BY fin_year;");
            // debug($arr_fin_year); exit;
            foreach($arr_fin_year as $fy){
                if(isset($fy['fin_year']['fin_year']) && isset($fy[0]['start_year']) && isset($fy[0]['end_year']))
                $result['options'][$fy['fin_year']['fin_year']] = $fy[0]['start_year']. '-' .$fy[0]['end_year'];
            }
        }

        return json_encode($result);
    }
