    ////The below function GenerateSalaryGrossPeriod Edited by ***ARUL P DAS on 29/11/2019*** Added branch wise report.
    
     private function GenerateSalaryGrossPeriod($mode) {//mode=>pdf,excel or just display.
        $arr_form_data = $_REQUEST;
        $this->EmpCtcTransaction->useDbConfig = $this->Session->read('ds');
        //edited by athira on 10-07-2025
       $company_code = strtoupper($this->Session->read('company_code')); //Edited by Akshay on 14-5-2024
       $this->set('company_code',$company_code);
      // end
        $arr_requestdata = $this->request->data;
        $resigned = $arr_form_data['resigned']; //Resigned or not. If it is resigned, value is 1. Else it is 0.
        $arr_keys = $this->EmpCtcTransaction->query("SELECT trim(salary_head_item_desc) as sal_head,head_operator FROM emp_salary_slip as ectc
                                                    left join salary_head_items as salhead on (salhead.salary_head_item_pkey = ectc.salary_head_item_fkey)
                                                    where ectc.item_part='Direct'                                         
                                                    Group by salary_head_item_desc
                                                    ORDER BY salhead.salary_head_item_order1 asc");
        $array_key = array();

        foreach ($arr_keys as $val) {
            if ($val['ectc']['head_operator'] == 'Addition') {
                $array_key['Addition'][] = $val[0]['sal_head'];
            } else {
                $array_key['Deduction'][] = $val[0]['sal_head'];
            }
        }

        $from = date('Y-m', strtotime($arr_form_data['reportfrom']));

        $from1 = date('F Y', strtotime($arr_form_data['reportfrom']));
        $to = date('Y-m', strtotime($arr_form_data['reportto']));
        $to1 = date('F Y', strtotime($arr_form_data['reportto']));
          // debug($from);
          // debug($to);exit();
        $otdate = date('Y-m-1', strtotime($arr_form_data['reportfrom']));
        $conditions = array();
        $conditions[] = 'ectc.month_year between "' . $from . '" and "' . $to . '" ';
        $arr_leavepolicygroupids = array();
        $int_criterias_count = $arr_form_data['hidden-criterias-count'];
        $criteria = '';
        $branches = $this->EmpCtcTransaction->query("select distinct branch_name,branch_code from branches"); //Here taking all branches. Its uses in branch wise
        $this->set('branches', $branches);
        for ($i = 1; $i <= $int_criterias_count; $i++) {
            $str_criteria_item = $arr_form_data['hidden-criteria' . $i];
            $criteria = $str_criteria_item;
            $this->set('criteria', $criteria);
            $arr_leavepolicygroupids = isset($arr_form_data[$str_criteria_item]) ? $arr_form_data[$str_criteria_item] : '';

            if ($str_criteria_item == '') {
                echo "<h1>No Criteria Selected</h1>";
                die();
            }

            if (!isset($arr_form_data[$str_criteria_item])) {
                echo "<h1>No Criteria Selected</h1>";
                die();
            }
        }
        $arr_salary_for_template = array();
        $id = implode(' AND ', $conditions);
        if (isset($arr_leavepolicygroupids) && !empty($arr_leavepolicygroupids))
            $k = 0;
        $gross = array();
        $arr_gross = array();
        // $arr_loop = array();
        //debug($arr_form_data);
        //Negative salary
        if(isset($arr_form_data['ngtvsal']) && $arr_form_data['ngtvsal'] =='1')
        {
            $conditions1 = " and ectc.payroll_master_fkey  in (select payroll_master_pkey from payroll_master where net_salary IS NOT NULL) ";
           
        }else{
            $conditions1 = " and ectc.payroll_master_fkey  in (select payroll_master_pkey from payroll_master where net_salary >=0) ";   
        }
        //debug($conditions1);exit;
    try{
        foreach ($arr_leavepolicygroupids as $leavepolicygroupid) {
            if ($criteria == "Units") {//This is the case of Branch wise.*********THIS BRANCH WISE SECTION BY ARUL P DAS 24/10/2019*************
                if ($resigned == 0) {//The query below only takes employees that are currently working.
                    $arr_gross = $this->EmpCtcTransaction->query(" select info.*,user_credentials.user_id,emp_ctc_transaction.emp_anual_ctc,"
                            . "termination.last_approved_working_date,emp_details.status,emp_details.classification,ectc.* from emp_salary_slip as ectc "
                            . " left join employee_info as info on (info.emp_pkey = ectc.emp_fkey)"
                            . "left join emp_details as emp_details on (emp_details.emp_pkey = ectc.emp_fkey)"
                            . "left join termination as termination on (termination.emp_fkey = info.emp_pkey and termination.status = 1)"
                            . "left join emp_ctc_transaction on (emp_ctc_transaction.emp_fkey = ectc.emp_fkey  and emp_ctc_transaction.end_date_effective is null )"
                            . "left join user_credentials as user_credentials on (user_credentials.emp_fkey = info.emp_pkey)"
                            . "where  emp_details.branch_code= '$leavepolicygroupid' $conditions1 "
                            . "AND emp_details.status = 1 "
                            . "AND ectc.item_part = 'Direct' and salary_amount != 0 "
                              . "AND ectc.month_year between '$from' and '$to' " 
                            . "AND ectc.end_date_effective is null  "
                            . "AND  $id  order by info.EmpName ");
                } else {
                    $arr_gross = $this->EmpCtcTransaction->query(" select info.*,user_credentials.user_id,emp_ctc_transaction.emp_anual_ctc,termination.last_approved_working_date,emp_details.classification,emp_details.status,ectc.* from emp_salary_slip as ectc "
                            . " left join employee_info as info on (info.emp_pkey = ectc.emp_fkey)"
