                            $key = array_search($data, $gross[$k]['SDeduction']['keys']); // $key = 2;
                            $gross[$k]['SDeduction']['value'][$key] += $value['ectc']['salary_amount'];
                            $gross[$k]['SDeduction']['actual'][$key] += $value['ectc']['structure_det_value'];
                        } else { 
                            $keys = isset($gross[$leavepolicygroupid][$emp_pkey]['VAddition']['keys'])?$gross[$leavepolicygroupid][$emp_pkey]['VAddition']['keys']:'';
