                            $key = array_search($data, $gross[$k]['VAddition']['keys']); // $key = 2;
                            if($key >= 0){
                            $gross[$k]['VAddition']['value'][$key] += $value['ectc']['salary_amount'];
                            $gross[$k]['VAddition']['actual'][$key] += $value['ectc']['structure_det_value'];
                            }
