                $arr_gross1 = $this->EmpCtcTransaction->query("select salary_heads.head_pkey,info.*,ar.weekoff_total,ar.holiday_total,ar.leave_total,ar.presant_total,user_credentials.user_id,emp_ctc_transaction.emp_derived_anualctc,termination.last_approved_working_date,emp_details.status,ectc.* from emp_salary_slip as ectc "
