    private function generatesalaryreport($mode) 
    {
        $arr_form_data = $_REQUEST;
        $this->EmpCtcTransaction->useDbConfig = $this->Session->read('ds');
        //edited by athira on 10-07-2025
        $company_code = strtoupper($this->Session->read('company_code')); //Edited by Akshay on 14-5-2024
        $this->set('company_code', $company_code);
        // end
        // edited by sinsiya on  04-10-2024
        $user_id = $this->Session->read('login_user_id');
        $date_time = date('d-m-y H:i');
        $this->set('user_id', $user_id);
        $this->set('date_time', $date_time);
        $arr_leavepolicygroupids = array();
        $int_criterias_count = $arr_form_data['hidden-criterias-count'];
        for ($i = 1; $i <= $int_criterias_count; $i++) {
            $str_criteria_item = $arr_form_data['hidden-criteria' . $i];

            $arr_leavepolicygroupids = isset($arr_form_data[$str_criteria_item]) ? $arr_form_data[$str_criteria_item] : '';

            if ($str_criteria_item == '') {
                echo "<h1>No Criteria Selected</h1>";
                die();
            }

            if (!isset($arr_form_data[$str_criteria_item])) {
                echo "<h1>No Criteria Selected</h1>";
                die();
            }
        }
        $condition = "and ed.status='1'";
        //        debug($arr_form_data);
        if (isset($arr_form_data['resigned']) && $arr_form_data['resigned'] == '1') {
            $condition = "and ed.status in ('1','2') ";
        }

        $arr_leavepolicydetails_for_template = array();
        if ($arr_leavepolicygroupids != '') {
            foreach ($arr_leavepolicygroupids as $leavepolicygroupid) {

                if ($arr_form_data['select-criteria1'] == 'Units') {
                    $arr_empleaverequests = $this->EmpCtcTransaction->query("SELECT 
                                                                                    ep.emp_branch,
                                                                                    uc.user_id,
                                                                                    ep.joining_date,
                                                                                    br.branch_name,
                                                                                    ed.first_name,
                                                                                    ed.last_name,
                                                                                    ed.status,
                                                                                    ed.emp_pkey,

                                                                                    IFNULL(SUM(ABS(ess.structure_det_value)),0) AS emp_derived_anualctc,

                                                                                    IFNULL(SUM(ABS(ess.structure_det_value)),0) * 12 AS emp_anual_ctc,

                                                                                    termination.last_approved_working_date,
                                                                                    desig.desig_name,
                                                                                    ep.emp_company_id,
                                                                                    dep.dept_name

                                                                                FROM emp_details ed

                                                                                LEFT JOIN emp_proff ep 
                                                                                    ON ep.emp_fkey = ed.emp_pkey

                                                                                LEFT JOIN emp_salary_structure ess 
                                                                                    ON ess.emp_fkey = ed.emp_pkey
                                                                                    AND (
                                                                                            ess.end_date_effective IS NULL
                                                                                            OR ess.end_date_effective = '0000-00-00'
                                                                                        )
                                                                                    AND ess.head_operator = 'Addition'

                                                                                LEFT JOIN user_credentials uc 
                                                                                    ON uc.emp_fkey = ed.emp_pkey

                                                                                LEFT JOIN termination termination 
                                                                                    ON termination.emp_fkey = ep.emp_fkey
                                                                                    AND termination.status = 1

                                                                                LEFT JOIN designation desig 
                                                                                    ON desig.desig_code = ep.designation
                                                                                    AND desig.status = 1

                                                                                LEFT JOIN department dep 
                                                                                    ON dep.dept_code = ep.emp_dept

                                                                                LEFT JOIN branches br
                                                                                    ON br.branch_code = ep.emp_branch
                                                                                
                                                                                LEFT JOIN salary_head_items shi
                                                                                    ON shi.salary_head_item_pkey = ess.salary_head_item_fkey

                                                                                WHERE ed.branch_code = '$leavepolicygroupid' $condition AND shi.head_fkey in (1,4,10)

                                                                                GROUP BY ed.emp_pkey ORDER BY ed.first_name ASC;");
                } else if ($arr_form_data['select-criteria1'] == 'EmployeeDetails') {
                    $arr_empleaverequests = $this->EmpCtcTransaction->query("SELECT 
                                                                                    ep.emp_branch,
                                                                                    uc.user_id,
                                                                                    ep.joining_date,
                                                                                    br.branch_name,
                                                                                    ed.first_name,
                                                                                    ed.last_name,
                                                                                    ed.status,
                                                                                    ed.emp_pkey,

                                                                                    IFNULL(SUM(ABS(ess.structure_det_value)),0) AS emp_derived_anualctc,

                                                                                    IFNULL(SUM(ABS(ess.structure_det_value)),0) * 12 AS emp_anual_ctc,

                                                                                    termination.last_approved_working_date,
                                                                                    desig.desig_name,
                                                                                    ep.emp_company_id,
                                                                                    dep.dept_name

                                                                                FROM emp_details ed

                                                                                LEFT JOIN emp_proff ep 
                                                                                    ON ep.emp_fkey = ed.emp_pkey

                                                                                LEFT JOIN emp_salary_structure ess 
                                                                                    ON ess.emp_fkey = ed.emp_pkey
                                                                                    AND (
                                                                                            ess.end_date_effective IS NULL
                                                                                            OR ess.end_date_effective = '0000-00-00'
                                                                                        )
                                                                                    AND ess.head_operator = 'Addition'
                                                                                    

                                                                                LEFT JOIN user_credentials uc 
                                                                                    ON uc.emp_fkey = ed.emp_pkey

                                                                                LEFT JOIN termination termination 
                                                                                    ON termination.emp_fkey = ep.emp_fkey
                                                                                    AND termination.status = 1

                                                                                LEFT JOIN designation desig 
                                                                                    ON desig.desig_code = ep.designation
                                                                                    AND desig.status = 1

                                                                                LEFT JOIN department dep 
                                                                                    ON dep.dept_code = ep.emp_dept

                                                                                LEFT JOIN branches br
                                                                                    ON br.branch_code = ep.emp_branch
                                                                                
                                                                                LEFT JOIN salary_head_items shi
                                                                                    ON shi.salary_head_item_pkey = ess.salary_head_item_fkey

                                                                                WHERE ed.emp_pkey = '$leavepolicygroupid' $condition AND shi.head_fkey in (1,4,10)

                                                                                GROUP BY ed.emp_pkey ORDER BY ed.first_name ASC;");
                }

                $arr_leavepolicydetails_for_template[] = array(
                    'summary' => $arr_empleaverequests,
                );
            }
        }


        $this->set('arr_leavepolicydetails_for_template', $arr_leavepolicydetails_for_template);
        $cr = $arr_form_data['select-criteria1'];
