            $leave[$emp] = isset($weekoff[$emp][0]['payroll_master']['days_leave']) ? $weekoff[$emp][0]['payroll_master']['days_leave'] : 0;
        }
         
         $day[$id][$emp]['present'] = isset($weekoff[$emp][0]['payroll_master']['days_presant']) ? $weekoff[$emp][0]['payroll_master']['days_presant'] + $leave[$emp] : 0; //$day['days'] - $lop;
      
        }
        if(!empty($day)){
         return $day;
        }else{
            return false;
        }
       
    }
