        public function listBankBranches($banks = '', $month = '') {
            $month = str_replace('"', '', $month);
            $this->autoRender = false;
            $this->EmployeeDetails->useDbConfig = $this->Session->read('ds');
            $banksArray = explode(',', $banks);
            $count = count($banksArray);
            if($count > 0){
                $banksArray[0] = ltrim($banksArray[0], '"');
                $banksArray[$count - 1] = rtrim($banksArray[$count - 1], '"');
            }
            $commaSeparatedString = implode("','", array_map(function($item) {
                return $item;
            }, $banksArray));
            $banks = trim($banks, "'");
            $arr_bank_branches = array();

            if($banks != '' && $banks != '""'){
                try{
                $arr_bank_branches = $this->EmployeeDetails->query("SELECT DISTINCT branches.branch_name, branches.branch_code FROM emp_details
                LEFT JOIN payroll_master ON (payroll_master.emp_fkey = emp_details.emp_pkey)
                LEFT JOIN branches ON (payroll_master.branch_code = branches.branch_code )
                WHERE
                    ((SUBSTRING_INDEX(payroll_master.bank_details, ',', 1) IN ('$commaSeparatedString')) OR (SUBSTRING_INDEX(payroll_master.bank_details, ',', 1) = '') OR (payroll_master.bank_details IS NULL))
                AND branches.status = 1
                -- AND payroll_master.month_year = '$month'
                ORDER BY branches.branch_name;
                ");
                }catch(Exception $e){
                    debug($e);
                }
            }

            $transformedArray = array_map(function($item) {
                return array(
                    'key' => $item['branches']['branch_code'],
                    'text' => $item['branches']['branch_name']
                );
            }, $arr_bank_branches);
            
            // Calculate the length of the transformed array
            $length = count($transformedArray);
            
            // Create an associative array to include both length and transformed data
            $response = $transformedArray;
            // debug($response);
            if($length > 0){
                return json_encode($response);
            }else{
                return json_encode($response);
            }
            // Encode the response into JSON format
        }
