                        LEFT JOIN 
                            employee_info AS info ON info.emp_pkey = ectc.emp_fkey
                        WHERE 
                            ectc.emp_fkey = '$leavepolicygroupid' 
                            AND STR_TO_DATE(ectc.month_year, '%Y-%m') BETWEEN STR_TO_DATE('$from', '%Y-%m') AND STR_TO_DATE('$todate', '%Y-%m') 
                            AND ectc.end_date_effective IS NULL 
                            $conditon2
