                                                                FROM payroll_transactions AS pt LEFT JOIN user_credentials AS uc ON (uc.user_id = pt.approved_by)
                                                                LEFT JOIN employee_info AS ei ON (ei.emp_pkey = uc.emp_fkey) WHERE pt.status = 1 AND pt.payroll_status IS NOT NULL AND pt.month_year = '$from'
                                                                AND pt.payroll_master_fkey IN (SELECT payroll_master_pkey FROM payroll_master
                                                                WHERE  month_year = '$from') AND pt.final_status IS NOT NULL group by payroll_status");
            }
