        // debug($arr_report);
        // debug($arr_custom_report);exit;

        function num2alpha($n)
        {
            $r = '';
            for ($i = 1; $n >= 0 && $i < 10; $i++) {
                $r = chr(0x41 + ($n % pow(26, $i) / pow(26, $i - 1))) . $r;
                $n -= pow(26, $i);
            }
            return $r;
        }

