     private function generatePayrollCTC( $type,$mode) 
    {
            $arr_form_data = $_REQUEST;
            $this->EmpCtcTransaction->useDbConfig = $this->Session->read('ds');
            $arr_requestdata = $this->request->data;
            $from = date('Y-m', strtotime($arr_form_data['reportfrom']));
            $otdate = date('Y-m-1', strtotime($arr_form_data['reportfrom']));
            $month = $arr_form_data['reportfrom'];

            // Helper function to build the result array
            function build_salary_result($keys, $salary_lookup) {
                $result = [];
                foreach ($keys as $item) {
                    $head = $item['ectc']['key'];
                    $sal_head = $item[0]['sal_head'];
                    $operator = $item['ectc']['head_operator'];

                    $amount = 0;
                    $rate = 0;

                    // Search salary_lookup for matching key + sal_head
                    if (isset($salary_lookup[$head])) {
                        if (
                            isset($salary_lookup[$head]['sal_head']) &&
                            $salary_lookup[$head]['sal_head'] === $sal_head
                        ) {
                            $amount = $salary_lookup[$head]['amount'];
                            $rate = $salary_lookup[$head]['rate'];
                        }
                    }

                    $result[] = [
                        'sal_head' => $sal_head,
                        'key' => $head,
                        'operator' => $operator,
                        'salary_amount' => $amount,
                        'salary_rate' => $rate
                    ];
                }
                return $result;
            }

            $standard_keys = $this->EmpCtcTransaction->query("select trim(salary_head_item_desc) as sal_head,ectc.head_operator, ectc.salary_head_item_fkey as `key` FROM emp_salary_slip as ectc
                left join salary_head_items as salhead on (salhead.salary_head_item_pkey = ectc.salary_head_item_fkey)
                left join salary_heads on (salary_heads.head_pkey = salhead.head_fkey) where ectc.item_part='Direct' and salary_heads.head_pkey in (1,5)
                and end_date_effective is null  and month_year = '$from' Group by salary_head_item_desc ORDER BY salhead.salary_head_item_order1 asc");
            // debug($standard_keys);

            $variable_keys = $this->EmpCtcTransaction->query("select trim(salary_head_item_desc) as sal_head,ectc.head_operator, ectc.salary_head_item_fkey as `key` FROM emp_salary_slip as ectc
                left join salary_head_items as salhead on (salhead.salary_head_item_pkey = ectc.salary_head_item_fkey)
                left join salary_heads on (salary_heads.head_pkey = salhead.head_fkey) where ectc.item_part='Direct' 
                -- and head_type != 'Manually' 
                and salary_heads.head_pkey in (2,7,9)
                and end_date_effective is null  and month_year = '$from' Group by salary_head_item_desc ORDER BY salhead.salary_head_item_order1 asc");
            // debug($variable_keys);

            $employer_keys = $this->EmpCtcTransaction->query("select trim(salary_head_item_desc) as sal_head,ectc.head_operator, ectc.salary_head_item_fkey as `key` FROM emp_salary_slip as ectc
                left join salary_head_items as salhead on (salhead.salary_head_item_pkey = ectc.salary_head_item_fkey)
                left join salary_heads on (salary_heads.head_pkey = salhead.head_fkey) where ectc.item_part='Indirect' and salary_heads.head_pkey = 4
                and end_date_effective is null  and month_year = '$from' Group by salary_head_item_desc ORDER BY salhead.salary_head_item_order1 asc");
            // debug($employer_keys);

        $actual_addition_keys = $this->EmpCtcTransaction->query("select trim(salary_head_item_desc) as sal_head,ectc.head_operator, ectc.salary_head_item_fkey as `key` FROM emp_salary_slip as ectc
                left join salary_head_items as salhead on (salhead.salary_head_item_pkey = ectc.salary_head_item_fkey)
                left join salary_heads on (salary_heads.head_pkey = salhead.head_fkey) where ectc.item_part='Direct' 
                and (head_type = 'Manually' or head_type = 'Fixed')
                and (salary_heads.head_pkey not in (1,5,2,7,9) OR salary_heads.head_pkey IS NULL )
                and ectc.head_operator = 'Addition'
                and end_date_effective is null  and month_year = '$from' Group by salary_head_item_desc ORDER BY salhead.salary_head_item_order1 asc");
            // debug($actual_addition_keys);

        $actual_deduction_keys = $this->EmpCtcTransaction->query("select trim(salary_head_item_desc) as sal_head,ectc.head_operator, ectc.salary_head_item_fkey as `key` FROM emp_salary_slip as ectc
                left join salary_head_items as salhead on (salhead.salary_head_item_pkey = ectc.salary_head_item_fkey)
                left join salary_heads on (salary_heads.head_pkey = salhead.head_fkey) where ectc.item_part='Direct' 
                and (head_type = 'Manually' or head_type = 'Fixed')
                and (salary_heads.head_pkey not in (1,5,2,7,9) OR salary_heads.head_pkey IS NULL )
                and ectc.head_operator = 'Deduction'
                and end_date_effective is null  and month_year = '$from' Group by salary_head_item_desc ORDER BY salhead.salary_head_item_order1 asc");

            // debug($actual_deduction_keys);exit;

            $standard_fkeys = [];
            foreach ($standard_keys as $item) {
                $fkey = $item['ectc']['key'];
                $standard_fkeys[] = $fkey;
            }

            // Extract keys
            $variable_fkeys = [];
            foreach ($variable_keys as $item) {
                $fkey = $item['ectc']['key'];
                $variable_fkeys[] = $fkey;
            }

            // Step 1: Extract fkeys from employer keys
            $employer_fkeys = [];
            foreach ($employer_keys as $item) {
                $fkey = $item['ectc']['key'];
                $employer_fkeys[] = $fkey;
            }

            $actual_additon_fkeys = [];
            foreach ($actual_addition_keys as $item) {
                $fkey = $item['ectc']['key'];
                $actual_additon_fkeys[] = $fkey;
            }
        
            $actual_dedcution_fkeys = [];
            foreach ($actual_deduction_keys as $item) {
                $fkey = $item['ectc']['key'];
                $actual_dedcution_fkeys[] = $fkey;
            }
        
        
            $array_key = array();
            $variable_key = array();
            $standard_key = array();
            $stdctc_key = array();
            $actualctc_key = array();

            $conditions = '';

            $arr_leavepolicygroupids = array();
            $int_criterias_count = $arr_form_data['hidden-criterias-count'];
            for ($i = 1; $i <= $int_criterias_count; $i++) {
                $str_criteria_item = $arr_form_data['hidden-criteria' . $i];
                $arr_leavepolicygroupids = isset($arr_form_data[$str_criteria_item]) ? $arr_form_data[$str_criteria_item] : '';
                //   belongs to branch section added by megha start 1...
                $needBranchWiseReport = false;
                if ($str_criteria_item == 'Units') {
                    $needBranchWiseReport = true;
                }
                $this->set('needBranchWiseReport', $needBranchWiseReport);
                if ($str_criteria_item == '') {
                    echo "<h1>No Criteria Selected</h1>";
                    die();
                }

                if (!isset($arr_form_data[$str_criteria_item])) {
                    echo "<h1>No Criteria Selected</h1>";
                    die();
                }
            }
            if (isset($arr_form_data['resigned']) && $arr_form_data['resigned'] == '1') {
                $condition = " AND ed.status in('1','2')";
            } else {
                $condition = " AND ed.status= 1";
            }
            //Negative Salary added.
            $condition2 = '';
            if (isset($arr_form_data['ngtvsal']) && $arr_form_data['ngtvsal'] == '1') {
                $condition2 = " AND pm.net_salary >= 0 ";
            }
            $arr_salary_for_template = array();
            $gross = array();

            if (isset($arr_leavepolicygroupids) && !empty($arr_leavepolicygroupids))
                $k = 0;
            try{
            $arr_emp_details = array();

            foreach ($arr_leavepolicygroupids as $leavepolicygroupid) {
                if ($arr_form_data['select-criteria1'] == 'EmployeeDetails') {

                    $arr_emp = $this->EmpCtcTransaction->query("
                                                        SELECT 
                                                            ei.employee_id AS `Employee ID`,
                                                            uc.user_id AS `User ID`,
                                                            ei.EmpName AS `Employee Name`,
                                                            CASE 
                                                                WHEN ed.classification = 'male' THEN 'Male'
                                                                WHEN ed.classification = 'female' THEN 'Female'
                                                                WHEN ed.classification = 'Other' THEN 'Transgender'
                                                                ELSE ed.classification
                                                            END AS `Gender`,
                                                            ar.month_year AS `Month`,
                                                            ei.designation AS `Designation`,
                                                            ei.department AS `Department`,
                                                            ei.branch AS `Branch`,
                                                            CASE 
                                                                WHEN ei.joining_date IS NOT NULL THEN DATE_FORMAT(ei.joining_date, '%d-%m-%Y')
                                                                ELSE ''
                                                            END AS `Date of Joining`,
                                                            CASE 
                                                                WHEN tm.last_approved_working_date IS NOT NULL THEN DATE_FORMAT(tm.last_approved_working_date, '%d-%m-%Y')
                                                                ELSE ''
                                                            END AS `Date of Termination`,
                                                            ar.presant_total AS `Present Days`,
                                                            ROUND(ot.total_duration / 60, 2) AS `Overtime (In Hrs.)`,
                                                            ar.lop_total AS `LOP Days`,
                                                            ar.leave_total AS `Leave Days`,
                                                            ar.weekoff_total AS `Week Off`,
                                                            ar.holiday_total AS `Holiday`
                                                        FROM 
                                                            attendance_register ar
                                                        LEFT JOIN 
                                                            emp_details ed ON ar.emp_fkey = ed.emp_pkey
                                                        LEFT JOIN 
                                                            employee_info ei ON ed.emp_pkey = ei.emp_pkey
                                                        LEFT JOIN 
                                                            emp_ot_master ot ON ar.emp_fkey = ot.emp_fkey 
                                                            AND DATE_FORMAT(ot.month, '%Y-%m') = LEFT(ar.month_year, 7)
                                                        LEFT JOIN 
                                                            termination tm ON (ar.emp_fkey = tm.emp_fkey AND tm.status = 1)
                                                        LEFT JOIN 
                                                            payroll_master pm ON pm.emp_fkey = ar.emp_fkey AND pm.month_year = ar.month_year
                                                        LEFT JOIN 
                                                        user_credentials uc ON uc.emp_fkey = ar.emp_fkey
                                                        WHERE 
                                                            ar.emp_fkey = $leavepolicygroupid
                                                            AND ar.isdelete = 'N'
                                                            AND ar.month_year = '$month'
                                                            AND ar.record_status = '1'
                                                            AND pm.action IN ('Approved', 'Processed')
                                                            -- AND tm.last_approved_working_date IS NOT NULL
                                                            -- AND DATE_FORMAT(tm.last_approved_working_date, '%Y-%m') = '$month'
                                                            $condition
                                                            $condition2
                                                            ORDER BY ed.first_name
                                                    ");

                    if(!empty($arr_emp)){

                    
                        $employee_salary = $this->EmpCtcTransaction->query("
                                                                            SELECT 
                                                                                ess.salary_head_item_fkey,
                                                                                TRIM(ess.salary_head_item_desc) AS sal_head,
                                                                                ess.structure_det_value,
                                                                                ess.salary_amount,
                                                                                ess.head_operator
                                                                            FROM emp_salary_slip AS ess
                                                                            LEFT JOIN salary_head_items AS shi ON shi.salary_head_item_pkey = ess.salary_head_item_fkey
                                                                            LEFT JOIN salary_heads AS sh ON sh.head_pkey = shi.head_fkey
                                                                            WHERE 
                                                                                ess.end_date_effective IS NULL
                                                                                AND ess.month_year = '$month'
                                                                                AND ess.emp_fkey = $leavepolicygroupid
                                                                            ORDER BY shi.salary_head_item_pkey ASC
                                                                        ");
                        
