                        $variable_result = build_salary_result($variable_keys, $salary_lookup);
                        $employer_result = build_salary_result($employer_keys, $salary_lookup);
                        $actual_addition_result = build_salary_result($actual_addition_keys, $salary_lookup); 
                        $actual_deduction_result = build_salary_result($actual_deduction_keys, $salary_lookup); 

                    }


                    if(!empty($arr_emp)){
                        $arr_emp_details[$emp_pkey]['Employee'] =  $arr_emp;
                        $arr_emp_details[$emp_pkey]['standard_additions'] =  $standard_additions;
                        $arr_emp_details[$emp_pkey]['standard_deductions'] =  $standard_deductions;
                        $arr_emp_details[$emp_pkey]['variable_result'] =  $variable_result;
                        $arr_emp_details[$emp_pkey]['employer_result'] =  $employer_result;
                        $arr_emp_details[$emp_pkey]['actual_addition_result'] =  $actual_addition_result;
                        $arr_emp_details[$emp_pkey]['actual_deduction_result'] =  $actual_deduction_result;
                    }
