                        $actual_addition_result = $group_data['actual_addition_result'];
                        $actual_deduction_result = $group_data['actual_deduction_result'];
                        
                        foreach ($arr_emp as $emp) {
                            $col = 0;

                            $writeVal = function($v) use (&$col, $row, $worksheet) {
                                $worksheet->setCellValueByColumnAndRow($col++, $row, $v);
                            };

                            $writeVal($slno++);

                            foreach (['Employee ID', 'User ID', 'Employee Name', 'Gender', 'Month', 'Designation', 'Department', 'Branch', 'Date of Joining', 'Date of Termination', 'Present Days', 'Overtime (In Hrs.)', 'LOP Days', 'Leave Days', 'Week Off', 'Holiday'] as $key) {
                                $val = '';
                                foreach ($emp as $section) {
                                    if (is_array($section) && array_key_exists($key, $section)) {
                                        $val = $section[$key];
                                        break;
                                    }
                                }
                                $writeVal($val);
                            }

                            $writeFromResult = function($list, $field) use (&$col, &$row, &$worksheet) {
                                foreach ($list as $item) {
                                    $worksheet->setCellValueByColumnAndRow($col++, $row, $item[$field]);
                                }
                            };


