                            $writeFromResult($standard_deductions, 'salary_rate');
                            $deductions_rate = array_sum(array_column($standard_deductions, 'salary_rate'));
                            $writeVal($deductions_rate);
                            $net_salary_rate = abs($gross_rate) - abs($deductions_rate);
                            $writeVal($net_salary_rate);
                            $writeFromResult($variable_result, 'salary_rate');
                            $variable_rate_total = array_sum(array_column($variable_result, 'salary_rate'));
                            $writeVal($variable_rate_total);
                            $writeFromResult($employer_result, 'salary_rate');
                            $employer_rate_total = array_sum(array_column($employer_result, 'salary_rate'));
                            $writeVal($employer_rate_total);
                            $writeVal($employer_rate_total + $gross_rate);

                            $writeFromResult($standard_additions, 'salary_amount');
                            $writeFromResult($variable_result, 'salary_amount');
                            $writeFromResult($actual_addition_result, 'salary_amount'); // Edited by Akshay on 12-6-2025
