                            $writeFromResult($standard_deductions, 'salary_amount');
                            $writeFromResult($actual_deduction_result, 'salary_amount'); // Edited by Akshay on 12-6-2025
                            $combined_deductions = array_merge($standard_deductions, $actual_deduction_result); // Edited by Akshay on 12-6-2025
                            $deductions = array_sum(array_column($combined_deductions, 'salary_amount')); // Edited by Akshay on 12-6-2025
                            $writeVal($deductions);
                            $net_salary = abs($gross) - abs($deductions);
                            $writeVal($net_salary);
                            $writeFromResult($employer_result, 'salary_amount');
                            $employer_amt_total = array_sum(array_column($employer_result, 'salary_amount'));
                            $writeVal($employer_amt_total);
                            $writeVal($employer_amt_total + $gross);

                            $row++;
                        }
                    }

