                    // exit;
                    $worksheet->setTitle(' Payroll CTC Report');
                    $objPHPExcel->getActiveSheet()->getHeaderFooter()
                        ->setOddFooter('&L Downloaded By ' . $user_name . '&R Page &P / &N')
