                    if(!empty($arr_emp_details))
                    $worksheet->getStyle("A4:{$lastColumn}{$lastRow}")->getBorders()->getAllBorders()->setBorderStyle(PHPExcel_Style_Border::BORDER_THIN);

                    // Fill the columns
                    // Light grey fill style
                    $lightGreyFill = [
                        'fill' => [
                            'type' => PHPExcel_Style_Fill::FILL_SOLID,
                            'color' => ['rgb' => 'D9D9D9'], // Light grey
                        ],
                    ];

                    
                    if(!empty($arr_emp_details)){
