                        // Apply to total row
                        $worksheet->getStyle("A{$totalRow}:{$lastColumn}{$totalRow}")->applyFromArray($lightGreyFill);
                    }


                    $objWriter = new PHPExcel_Writer_Excel2007($objPHPExcel);
