                                for ($m = 0; $m < $count_addition; $m++) {
                                    $number = round($val['SDeduction']['actual'][$m],2);
                                    $val1 = round($number,2);
                                    $objPHPExcel->getActiveSheet()->SetCellValue(PHPExcel_Cell::stringFromColumnIndex($col + 1) . $rowcount, $val1);
                                    $col++;
                                }
                            }
                            if($count > 0){
                            $count_addition1= count($val['VAddition']['keys']); 
                            $grss_amt1 = 0;
                            for($m=0;$m<$count_addition1;$m++)
                            {
                            $number1=round($val['VAddition']['actual'][$m]);
                            $grss_amt1 = $number1 + $grss_amt1;
                                $val1 = round($number1);
                                $objPHPExcel->getActiveSheet()->SetCellValue(PHPExcel_Cell::stringFromColumnIndex($col + 1) . $rowcount, $val1);
                                $col++;
                            }
                            $grss_amt1 = round($grss_amt1);
                            $objPHPExcel->getActiveSheet()->SetCellValue(PHPExcel_Cell::stringFromColumnIndex($col + 1) . $rowcount, $grss_amt1);
                            $col = $col + 1;
                            }
                            $count_addition = count($val['Addition']['keys']);
                            $grss_amt = 0;
                            for ($m = 0; $m < $count_addition; $m++) {
                                $number = round($val['Addition']['value'][$m]);
                                $grss_amt = $number + $grss_amt;

                                $val1 = round($number);
                                $objPHPExcel->getActiveSheet()->SetCellValue(PHPExcel_Cell::stringFromColumnIndex($col + 1) . $rowcount, $val1);
                                $col++;
                            }
                            
                            $grss_amt = round($grss_amt);
                            $objPHPExcel->getActiveSheet()->SetCellValue(PHPExcel_Cell::stringFromColumnIndex($col + 1) . $rowcount, $grss_amt);

                            $col = $col + 1;
                            $dd_amt = 0;
                            if (isset($array_key['Deduction'])) {
                                $count_addition = count($val['Deduction']['keys']);
                                for ($m = 0; $m < $count_addition; $m++) {
                                    $number = round($val['Deduction']['value'][$m], 2);
                                    $dd_amt = $number + $dd_amt;

                                    $val1 = round($number,2);
                                    $objPHPExcel->getActiveSheet()->SetCellValue(PHPExcel_Cell::stringFromColumnIndex($col + 1) . $rowcount, $val1);
                                    $col++;
                                }
                            }
                            $netamt = $grss_amt + $dd_amt + $settlement;
                            $dd_amt = round($dd_amt,2);
                            $objPHPExcel->getActiveSheet()->SetCellValue(PHPExcel_Cell::stringFromColumnIndex($col + 1) . $rowcount, $dd_amt);
                            //edited by megha on 13/11/2019 settlement amount 12
                            $objPHPExcel->getActiveSheet()->SetCellValue(PHPExcel_Cell::stringFromColumnIndex($col + 2) . $rowcount, $settlement);
                            $objPHPExcel->getActiveSheet()->SetCellValue(PHPExcel_Cell::stringFromColumnIndex($col + 3) . $rowcount, round($netamt));

                            $j++;
                            $rowcount++;
                        }
                        //   belongs to branch section added by megha 5...
                    }
                }
//                                     
                $objPHPExcel->getActiveSheet()->setTitle(' Salary Combined Report');
                /* header footer */
                $objPHPExcel->getActiveSheet()->getHeaderFooter()->setOddFooter('&L Downloaded By ' . $user_name . '&R Page &P / &N');
                $objPHPExcel->getActiveSheet()->getHeaderFooter()->setEvenFooter('&L Downloaded By ' . $user_name . '&R Page &P / &N');
                $objPHPExcel->getActiveSheet()->getHeaderFooter()->setOddHeader($arr_comp_contact_info['CompanyContactInfo']['business_name']);
                $objPHPExcel->getActiveSheet()->getHeaderFooter()->setEvenHeader($arr_comp_contact_info['CompanyContactInfo']['business_name']);
                /* header footer */
                /* print Set up */
                $objPHPExcel->getActiveSheet()->getPageSetup()->setPaperSize(PHPExcel_Worksheet_PageSetup::PAPERSIZE_A4);
                $objPHPExcel->getActiveSheet()->getPageSetup()->setFitToPage(true);
                $objPHPExcel->getActiveSheet()->getPageSetup()->setFitToWidth(1);
                $objPHPExcel->getActiveSheet()->getPageSetup()->setFitToHeight(0);
                /* print Set up */
                $objWriter = new PHPExcel_Writer_Excel2007($objPHPExcel);
                $objWriter->save(dirname(__FILE__) . "/" . $file_name);
                // output headers so that the file is downloaded rather than displayed
                header('Content-Type: application/vnd.ms-excel; charset=utf-8');
                header('Content-Disposition: attachment; filename=' . $file_name);

                readfile(dirname(__FILE__) . "/" . $file_name);
                unlink(dirname(__FILE__) . "/" . $file_name);
                break;
            default :
                $this->set('mode', '');
                $this->render('salary_combined');
                break;
        }
    }
