     private function GenerateSalaryGrossSummaryPSQUARE($mode) {
        $arr_form_data = $_REQUEST;
        $this->EmpCtcTransaction->useDbConfig = $this->Session->read('ds');
        //edited by sinsiya  on 30-10-2024
         $company_code = strtoupper($this->Session->read('company_code'));
         $this->set('company_code',$company_code);
        
         
        $arr_keys = $this->EmpCtcTransaction->query("SELECT trim(salary_head_item_desc) as sal_head,head_operator FROM emp_salary_slip as ectc
                                                    where item_part='Direct' Group by salary_head_item_desc
                                                    ORDER BY emp_salary_slip_pkey");
        $array_key = array();

        foreach ($arr_keys as $val) {

            if ($val['ectc']['head_operator'] == 'Addition') {
                $array_key['Addition'][] = $val[0]['sal_head'];
            } else {
                $array_key['Deduction'][] = $val[0]['sal_head'];
            }
        }

        $from = date('Y-m', strtotime($arr_form_data['reportfrom']));
        $from1 = date('F Y', strtotime($arr_form_data['reportfrom']));
        $otdate = date('Y-m-1', strtotime($arr_form_data['reportfrom']));
        $conditions = array();
        $conditions[] = 'ectc.month_year="' . $from . '"';
        $arr_leavepolicygroupids = array();
        $int_criterias_count = $arr_form_data['hidden-criterias-count'];
        for ($i = 1; $i <= $int_criterias_count; $i++) {

            $str_criteria_item = $arr_form_data['hidden-criteria' . $i];

            if ($str_criteria_item == '') {
                echo "<h1>No Criteria Selected</h1>";
                die();
            }

            if (!isset($arr_form_data[$str_criteria_item])) {
                echo "<h1>No Criteria Selected</h1>";
                die();
            }
            $arr_leavepolicygroupids = isset($arr_form_data[$str_criteria_item]) ? $arr_form_data[$str_criteria_item] : '';
        }
        $arr_leavepolicydetails_for_template = array();
        $id = implode(' AND ', $conditions);
        if (isset($arr_leavepolicygroupids) && !empty($arr_leavepolicygroupids))
            $k = 0;
        $gross = array();
        $criteria = $arr_form_data['hidden-criteria1']; //Units or EmployeeDetails
        $this->set('criteria', $criteria);

        //Coditions for negative salary and include resigned
            $resigned = $arr_form_data['resigned']; //Resigned or not. If it is resigned, value is 1. Else it is 0.
            if ($resigned == 0) {
                $condition = "AND emp_details.status = 1";
            } else {
                $condition = "AND emp_details.status in (1,2)";
            }
         
             //Negative Salary added by ASHIN on 19-06-24
             if(isset($arr_form_data['ngtvsal']) && $arr_form_data['ngtvsal'] =='1')
             {
                 $condition .= " ";
             
             }else{
                 $condition .= " and ectc.payroll_master_fkey  in (select payroll_master_pkey from payroll_master where net_salary >=0) ";   
             }
          
     
        foreach ($arr_leavepolicygroupids as $leavepolicygroupid) {

            if ($criteria == 'Units') {//This is the case of branch wise.*********THIS BRANCH WISE SECTION BY ARUL P DAS 16/10/2019*************
                $branches = $this->EmpCtcTransaction->query("SELECT DISTINCT branches.branch_name, payroll_master.branch_code 
                                            FROM payroll_master  
                                            LEFT JOIN branches  ON payroll_master.branch_code = branches.branch_code"); //Here taking all branches. Its uses in branch wise
                $this->set('branches', $branches);
                // $resigned = $arr_form_data['resigned']; //Resigned or not. If it is resigned, value is 1. Else it is 0.
                // if ($resigned == 0) {
                //     $condition = "AND emp_details.status = 1";
                // } else {
                //     $condition = "AND emp_details.status in (1,2)";
                // }
    //edited by ASHIN on 10-01-25            
                $arr_gross = $this->EmpCtcTransaction->query(" select info.*,payroll_master.*,user_credentials.user_id,branches.branch_name,branches.branch_code,termination.last_approved_working_date,"   //edited by Ashin 18-04-24
                        . "emp_details.status,ar.weekoff_total,ar.holiday_total,ectc.* from emp_salary_slip as ectc "
                        . " left join employee_info as info on (info.emp_pkey = ectc.emp_fkey)"
                        . " left join payroll_master as payroll_master on (payroll_master.payroll_master_pkey = ectc.payroll_master_fkey)"  //edited by Ashin 01-05-24
                        . " left join emp_details as emp_details on (emp_details.emp_pkey = ectc.emp_fkey)"
                        . " left join branches as branches on (payroll_master.branch_code = branches.branch_code and branches.status = 1) "
                        . " left join attendance_register as ar on (ar.emp_fkey = emp_details.emp_pkey)"
                        . " left join termination as termination on (termination.emp_fkey = emp_details.emp_pkey and termination.status = 1)"
                        . "left join emp_ctc_transaction on (emp_ctc_transaction.emp_fkey = ectc.emp_fkey  and emp_ctc_transaction.end_date_effective is null )"
                        . " left join user_credentials as user_credentials on (user_credentials.emp_fkey = emp_details.emp_pkey)"
                        . "where  payroll_master.branch_code= '$leavepolicygroupid' "   
                        . "$condition "
                        . "AND ectc.item_part = 'Direct' "
                        . "AND ectc.end_date_effective is null "
                        . " and ar.month_year= '$from' and ar.isdelete='N' "
                        . "AND  $id  order by info.EmpName");
                $arr_gross1 = $this->EmpCtcTransaction->query(" select info.*,payroll_master.*,user_credentials.user_id,branches.branch_name, branches.branch_code,termination.last_approved_working_date," //edited by Ashin on 18-06-24
                        . "emp_details.status,ar.weekoff_total,ar.holiday_total,ectc.* from emp_salary_slip as ectc "
                        . " left join employee_info as info on (info.emp_pkey = ectc.emp_fkey)"
