        . 'EmployeeDetails.first_name,middile_name,EmployeeDetails.last_name,ar.weekoff_total,ar.holiday_total,ar.presant_total,'
        . 'EmployeeDetails.status '
        . 'from payroll_master  '
        . 'left join emp_proff as ep on(ep.emp_fkey = payroll_master.emp_fkey) '
