                            $objPHPExcel->getActiveSheet()->getStyle(PHPExcel_Cell::stringFromColumnIndex(17))->getNumberFormat()->setFormatCode(PHPExcel_Style_NumberFormat::FORMAT_TEXT);

                            // Edited by Akshay on 25-7-2025
                            $objPHPExcel->getActiveSheet()->SetCellValue(PHPExcel_Cell::stringFromColumnIndex(18) . $rowcount, $stdgross); // Edited by Akshay on 18-8-2025
                            $objPHPExcel->getActiveSheet()->getStyle(PHPExcel_Cell::stringFromColumnIndex(18))->getNumberFormat()->setFormatCode(PHPExcel_Style_NumberFormat::FORMAT_TEXT);
                            // End

                            $objPHPExcel->getActiveSheet()->SetCellValue(PHPExcel_Cell::stringFromColumnIndex(19) . $rowcount, $grosssal);
                            $objPHPExcel->getActiveSheet()->getStyle(PHPExcel_Cell::stringFromColumnIndex(19))->getNumberFormat()->setFormatCode(PHPExcel_Style_NumberFormat::FORMAT_TEXT);
                            $objPHPExcel->getActiveSheet()->SetCellValue(PHPExcel_Cell::stringFromColumnIndex(20) . $rowcount, $ded);
                            $objPHPExcel->getActiveSheet()->getStyle(PHPExcel_Cell::stringFromColumnIndex(20))->getNumberFormat()->setFormatCode(PHPExcel_Style_NumberFormat::FORMAT_TEXT);
                            //                            $objPHPExcel->getActiveSheet()->SetCellValue(PHPExcel_Cell::stringFromColumnIndex(17) . $rowcount, $totalvar);
                            //                            $objPHPExcel->getActiveSheet()->getStyle(PHPExcel_Cell::stringFromColumnIndex(17))->getNumberFormat()->setFormatCode(PHPExcel_Style_NumberFormat::FORMAT_TEXT);

                            $objPHPExcel->getActiveSheet()->SetCellValue(PHPExcel_Cell::stringFromColumnIndex(21) . $rowcount, $settle);
                            $objPHPExcel->getActiveSheet()->getStyle(PHPExcel_Cell::stringFromColumnIndex(21))->getNumberFormat()->setFormatCode(PHPExcel_Style_NumberFormat::FORMAT_TEXT);
                            $objPHPExcel->getActiveSheet()->SetCellValue(PHPExcel_Cell::stringFromColumnIndex(22) . $rowcount, $net);
                            $objPHPExcel->getActiveSheet()->getStyle(PHPExcel_Cell::stringFromColumnIndex(22))->getNumberFormat()->setFormatCode(PHPExcel_Style_NumberFormat::FORMAT_TEXT);
                            $objPHPExcel->getActiveSheet()->SetCellValue(PHPExcel_Cell::stringFromColumnIndex(23) . $rowcount, $verified);
                            $objPHPExcel->getActiveSheet()->getStyle(PHPExcel_Cell::stringFromColumnIndex(23))->getNumberFormat()->setFormatCode(PHPExcel_Style_NumberFormat::FORMAT_TEXT);
                            //edited by megha  standard gross salary 8 end

                            for ($j = 0; $j <= 23; $j++) {
                                $objPHPExcel->getActiveSheet()->getStyleByColumnAndRow($j, $rowcount)->applyFromArray($leftstyle); //left alignment
                            }
                            $end_heading = 23;
                            $rowcount++;
                            $i++;
                        }
                    } 
                    //edited by ASHIN on 28-05-24        
                    $objPHPExcel->getActiveSheet()->mergeCells('A' . $rowcount . ':F' . $rowcount);
                    $objPHPExcel->getActiveSheet()->SetCellValue('A' . $rowcount, 'TOTAL');
                    $objPHPExcel->getActiveSheet()->getStyle('A' . $rowcount)->getFont()->setBold(true);
                    $objPHPExcel->getActiveSheet()->getStyle('A' . $rowcount)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                    $column = 12;
                    foreach ($total_val as $print_total) {
                        $objPHPExcel->getActiveSheet()->SetCellValue(PHPExcel_Cell::stringFromColumnIndex($column) . $rowcount, (isset($print_total) ? $print_total : ''));
                        $objPHPExcel->getActiveSheet()->getStyleByColumnAndRow($column, $rowcount)->getFont()->setBold(true);
                        $column++;
                    }
                }
            }


            //edited by ASHIN on 29-05-24
            $objPHPExcel->getActiveSheet()->setShowGridlines(false);
            //Border style
            $styleArray = array(
                'borders' => array(
                    'allborders' => array(
                        'style' => PHPExcel_Style_Border::BORDER_THIN
                    )
                )
            );
            $objPHPExcel->getActiveSheet()->setShowGridlines(false);
            $lastrow = $objPHPExcel->getActiveSheet()->getHighestRow();
            $objPHPExcel->getActiveSheet()->getStyle('A3:' . num2alpha($end_heading) . $rowcount)->applyFromArray($styleArray);

            $objPHPExcel->getActiveSheet()->setTitle('Payroll Summary');
            /* header footer */
            $objPHPExcel->getActiveSheet()->getHeaderFooter()->setOddFooter('&L Downloaded By ' . $user_name . '&R Page &P / &N');
            $objPHPExcel->getActiveSheet()->getHeaderFooter()->setEvenFooter('&L Downloaded By ' . $user_name . '&R Page &P / &N');
            $objPHPExcel->getActiveSheet()->getHeaderFooter()->setOddHeader($arr_comp_contact_info['CompanyContactInfo']['business_name']);
            $objPHPExcel->getActiveSheet()->getHeaderFooter()->setEvenHeader($arr_comp_contact_info['CompanyContactInfo']['business_name']);
            /* header footer */

            /* print Set up */
            $objPHPExcel->getActiveSheet()->getPageSetup()->setPaperSize(PHPExcel_Worksheet_PageSetup::PAPERSIZE_A4);
            $objPHPExcel->getActiveSheet()->getPageSetup()->setFitToPage(true);
            $objPHPExcel->getActiveSheet()->getPageSetup()->setFitToWidth(1);
            $objPHPExcel->getActiveSheet()->getPageSetup()->setFitToHeight(0);
            /* print Set up */

            $objWriter = new PHPExcel_Writer_Excel2007($objPHPExcel);
            $objWriter->save(dirname(__FILE__) . "/" . $file_name);

            // output headers so that the file is downloaded rather than displayed
            header('Content-Type: application/vnd.ms-excel; charset=utf-8');
            header('Content-Disposition: attachment; filename=' . $file_name);

            readfile(dirname(__FILE__) . "/" . $file_name);
            unlink(dirname(__FILE__) . "/" . $file_name);
            break;
        default:
            $this->set('mode', '');
            $this->render('payrolsummaryreports');
            break;
    }
}


