   ");
                $fin_year = $fin_year_query['0']['fy']['fin_year'];

                // Edited by Akshay on 29-12-2025
                $LBY = $this->EmpCtcTransaction->query("SELECT IFNULL(SUM(balance), 0) as LBY FROM monthly_leave_balance mlb
