        function numberToWords($number)
        {
            $f = new NumberFormatter("en", NumberFormatter::SPELLOUT);
            $words = $f->format($number);

            // Remove hyphens and capitalize each word
            return ucwords(str_replace('-', ' ', $words));
        }




