                        }
                    }
                    //edited by athira on 17-06-2025
                } else {
                    $rowcount = 4; // set row just after the title
                    $worksheet->setCellValue('A' . $rowcount, 'No data available under the selected criteria.');
                    $worksheet->mergeCells("A{$rowcount}:J{$rowcount}");
                    $worksheet->getStyle("A{$rowcount}")->getFont()->setBold(true)->setSize(14);
                }
                //end
                $objPHPExcel->getActiveSheet()->setTitle('Salary Report');

                $objWriter = new PHPExcel_Writer_Excel2007($objPHPExcel);
                $objWriter->save(dirname(__FILE__) . "/" . $file_name);

                // output headers so that the file is downloaded rather than displayed
                header('Content-Type: application/vnd.ms-excel; charset=utf-8');
                header('Content-Disposition: attachment; filename=' . $file_name);

                readfile(dirname(__FILE__) . "/" . $file_name);
                unlink(dirname(__FILE__) . "/" . $file_name);
                break;
            default:
                $this->set('mode', '');
                //Edited by Akshay on 14-5-2024
                if ($company_code == 'HRBL') {
                    $this->render('synthite_salaryslip');
                } else if ($company_code == 'SHYD' || $company_code == 'DEMO' || $company_code == 'GAAR') {
                    $this->render('sbl_salaryslip');
                } else {
                    $this->render('salaryslip');
                }
                break;
        }
    }
}
