                    }

                    //Background color for heading
                    $objPHPExcel->getActiveSheet()
                        ->getStyle('A4:' . num2alpha($end_heading) . '4')
                        ->getFill()
                        ->setFillType(PHPExcel_Style_Fill::FILL_SOLID)
                        ->getStartColor()
                        ->setRGB('C8C8C8');
                    //Background color for Total
                    $objPHPExcel->getActiveSheet()
                        ->getStyle('A' . $rowcount . ':' . num2alpha($end_heading) . $rowcount)
                        ->getFill()
                        ->setFillType(PHPExcel_Style_Fill::FILL_SOLID)
                        ->getStartColor()
                        ->setRGB('C8C8C8');
                }

                //                              //Hide gridlines
                $objPHPExcel->getActiveSheet()->setShowGridlines(false);

                //Border
                $lastrow = $objPHPExcel->getActiveSheet()->getHighestRow();
                //Edited by Akshay on 8-8-2024
                if ($empty == false) {
                    $objPHPExcel->getActiveSheet()->getStyle('A3:' . num2alpha($end_heading) . $rowcount)->applyFromArray($styleArray);
                }
                //End

                $objPHPExcel->getActiveSheet()->setTitle('Gross Salary Detailed');
                /* header footer */
                $objPHPExcel->getActiveSheet()->getHeaderFooter()->setOddFooter('&L Downloaded By ' . $user_name . '&R Page &P / &N');
                $objPHPExcel->getActiveSheet()->getHeaderFooter()->setEvenFooter('&L Downloaded By ' . $user_name . '&R Page &P / &N');
                $objPHPExcel->getActiveSheet()->getHeaderFooter()->setOddHeader($arr_comp_contact_info['CompanyContactInfo']['business_name']);
                $objPHPExcel->getActiveSheet()->getHeaderFooter()->setEvenHeader($arr_comp_contact_info['CompanyContactInfo']['business_name']);
                /* header footer */
                /* print Set up */
                $objPHPExcel->getActiveSheet()->getPageSetup()->setPaperSize(PHPExcel_Worksheet_PageSetup::PAPERSIZE_A4);
                $objPHPExcel->getActiveSheet()->getPageSetup()->setFitToPage(true);
                $objPHPExcel->getActiveSheet()->getPageSetup()->setFitToWidth(1);
                $objPHPExcel->getActiveSheet()->getPageSetup()->setFitToHeight(0);
                /* print Set up */
                $objWriter = new PHPExcel_Writer_Excel2007($objPHPExcel);
                $objWriter->save(dirname(__FILE__) . "/" . $file_name);
                // output headers so that the file is downloaded rather than displayed
                header('Content-Type: application/vnd.ms-excel; charset=utf-8');
                header('Content-Disposition: attachment; filename=' . $file_name);

                readfile(dirname(__FILE__) . "/" . $file_name);
                unlink(dirname(__FILE__) . "/" . $file_name);
                break;
            default:
                $this->set('mode', '');
                $this->render('grossreport_kwmt');
                break;
        }
    }
    // End

    // Edited by Akshay on 5-1-2025
    private function GenerateSalaryAccountReport($mode)
    {   
        $arr_form_data = $_REQUEST;
        $this->EmpCtcTransaction->useDbConfig = $this->Session->read('ds');
        
        $report_type = $arr_form_data['report_type'];
        $report_from = $arr_form_data['reportfrom'];
        $this->set('report_type', $report_type);
        $this->set('report_from', $report_from);

        $period_join_condtion_settlement = '';
        if($report_type == 'M'){
            $from = date('Y-m', strtotime($arr_form_data['reportfrom']));
            $month1 = $from .'-01';
            $arr_att_enddate = $this->EmpCtcTransaction->query("select att_start_end_fn(DATE_FORMAT('$month1', '%Y-%m-01'), 2) as monthly_att_todate");
            $att_enddate = $arr_att_enddate['0']['0']['monthly_att_todate'];
            $period_cond = "AND ectc.month_year = '$from' ";

            $period_condtion_settlement = " AND date_format(termination.last_approved_working_date,'%Y-%m') = '$from' ";
        }else{
            // $fy = $arr_form_data['reportfrom'];
            // $att_enddate = $fy."-12-31";
            // $period_cond = "
            //                 AND att_start_end_fn(DATE_FORMAT(CONCAT(ectc.month_year, '-01'), '%Y-%m-01'), 1)
            //                 BETWEEN
            //                 (
            //                     SELECT fin.start_month
            //                     FROM fin_year fin
            //                     WHERE fin.fin_year = '$fy'
            //                     AND fin.vattr1 = 1
            //                     AND fin.status = 1
            //                     AND fin.branch_code = pm.branch_code
            //                     LIMIT 1
            //                 )
            //                 AND
            //                 (
            //                     SELECT fin.end_month
            //                     FROM fin_year fin
            //                     WHERE fin.fin_year = '$fy'
            //                     AND fin.vattr1 = 1
            //                     AND fin.status = 1
            //                     AND fin.branch_code = pm.branch_code
            //                     LIMIT 1
            //                 )
            //                 ";

            // $period_condtion_settlement = "
            //     AND termination.last_approved_working_date BETWEEN
            //     (
            //         SELECT fin.start_month
            //         FROM fin_year fin
            //         WHERE fin.fin_year = '$fy'
            //         AND fin.vattr1 = 1
            //         AND fin.status = 1
            //         AND fin.branch_code = ed.branch_code
            //         ORDER BY fin.start_month DESC
            //         LIMIT 1
            //     )
            //     AND
            //     (
            //         SELECT fin.end_month
            //         FROM fin_year fin
            //         WHERE fin.vattr1 = 1
            //         AND fin.status = 1
            //         AND fin.branch_code = ed.branch_code
            //         ORDER BY fin.start_month DESC
            //         LIMIT 1
            //     )
            // ";
            
            $from = date('Y-m', strtotime($arr_form_data['reportfrom']));
            $to = date('Y-m', strtotime($arr_form_data['reportto']));
            $report_to = $arr_form_data['reportto'];
            $this->set('report_to', $report_to);

            $month1 = $to .'-01';
            $arr_att_enddate = $this->EmpCtcTransaction->query("select att_start_end_fn(DATE_FORMAT('$month1', '%Y-%m-01'), 2) as monthly_att_todate");
            $att_enddate = $arr_att_enddate['0']['0']['monthly_att_todate'];
            $period_cond = "AND ectc.month_year BETWEEN '$from' AND '$to' ";

            $period_condtion_settlement = " AND date_format(termination.last_approved_working_date,'%Y-%m') BETWEEN '$from' AND '$to' ";
        }


        $this->set('att_enddate', $att_enddate);

        $arr_leavepolicygroupids = array();
        $int_criterias_count = $arr_form_data['hidden-criterias-count'];
        for ($i = 1; $i <= $int_criterias_count; $i++) {
            $str_criteria_item = $arr_form_data['hidden-criteria' . $i];
            $arr_leavepolicygroupids = isset($arr_form_data[$str_criteria_item]) ? $arr_form_data[$str_criteria_item] : '';

            if ($str_criteria_item == '') {
                echo "<h1>No Criteria Selected</h1>";
                die();
            }

            if (!isset($arr_form_data[$str_criteria_item])) {
                echo "<h1>No Criteria Selected</h1>";
                die();
            }
        }

        $leavepolicyids = "'" .implode("','", $arr_leavepolicygroupids). "'";
        $needBranchWiseReport = false;
        if ($str_criteria_item == 'Units') {
            $needBranchWiseReport = true;
        }
        $this->set('needBranchWiseReport', $needBranchWiseReport);

        if($needBranchWiseReport){
            $condition = " AND pm.branch_code IN ($leavepolicyids) ";
        }else{
            $condition = " AND ed.emp_pkey IN ($leavepolicyids) ";
        }


        if (isset($arr_form_data['resigned']) && $arr_form_data['resigned'] == '1') {
            $condition .= "and ed.status in ('1','2') ";
            $period_condtion_settlement .= $condition;
        }else{
            $condition .= "and ed.status = '1'  ";
            $period_condtion_settlement .= $condition;
        }
        
            if($report_type == 'M'){
                $period_join_condtion_settlement .= " INNER JOIN payroll_master pm
                                                            ON pm.emp_fkey = ed.emp_pkey
                                                            AND pm.month_year = '$from' 
                                                        ";
            }else{
                $period_join_condtion_settlement .= " INNER JOIN payroll_master pm
                                                            ON pm.emp_fkey = ed.emp_pkey
                                                            AND pm.month_year BETWEEN '$from' AND '$to'
                                                        ";
            }  

        if (isset($arr_form_data['ngtvsal']) && $arr_form_data['ngtvsal'] == '0'){
            $condition .= " and pm.net_salary >=0 ";         
            $period_condtion_settlement .= " AND pm.action IN ('Approved','Processed') AND pm.net_salary >= 0 ";   
        }

        $arr_salary_for_template = array();
        $arr_empleaverequests = array();


        $monthly_components_cond = " AND ectc.salary_head_item_fkey IN (SELECT salary_head_item_pkey  FROM `salary_head_items` WHERE `head_fkey` IN ( 1, 4) ) ";

        $variable_components_cond = " AND ectc.salary_head_item_fkey IN (SELECT	salary_head_item_pkey  FROM `salary_head_items` WHERE `head_fkey` NOT IN ( 1, 4) ) ";

        
        // Montly components
        $arr_monthly_components = $this->EmpCtcTransaction->query("
                                                                SELECT
                                                                    ectc.salary_head_item_fkey,
                                                                    MAX(ectc.head_operator) AS head_operator,
                                                                    MAX(ectc.head_type) AS head_type,
                                                                    MAX(ectc.item_part) AS item_part,
                                                                    MAX(ectc.salary_head_item_desc) AS salary_head_item_desc,
                                                                    SUM(ectc.salary_amount) AS total_salary_amount
                                                                FROM emp_salary_slip ectc
                                                                INNER JOIN payroll_master pm
                                                                    ON pm.payroll_master_pkey = ectc.payroll_master_fkey
                                                                LEFT JOIN emp_details ed ON ed.emp_pkey = pm.emp_fkey
                                                                
                                                                WHERE ROUND(ectc.salary_amount) != 0
                                                                AND pm.action IN ('Approved','Processed')
                                                                $period_cond
                                                                $condition
                                                                AND ectc.end_date_effective IS NULL
                                                                AND ectc.head_operator = 'Addition'
                                                                AND ectc.item_part = 'Direct'
                                                                $monthly_components_cond
                                                                GROUP BY ectc.salary_head_item_fkey
                                                            ");

        

        // Employer contributions
        $arr_indirect_contribution = $this->EmpCtcTransaction->query("
                                                                SELECT
                                                                    ectc.salary_head_item_fkey,
                                                                    MAX(ectc.head_operator) AS head_operator,
                                                                    MAX(ectc.head_type) AS head_type,
                                                                    MAX(ectc.item_part) AS item_part,
                                                                    MAX(ectc.salary_head_item_desc) AS salary_head_item_desc,
                                                                    SUM(ectc.salary_amount) AS total_salary_amount
                                                                FROM emp_salary_slip ectc
                                                                INNER JOIN payroll_master pm
                                                                    ON pm.payroll_master_pkey = ectc.payroll_master_fkey
                                                                LEFT JOIN emp_details ed ON ed.emp_pkey = pm.emp_fkey
                                                                
                                                                WHERE ROUND(ectc.salary_amount) != 0
                                                                AND pm.action IN ('Approved','Processed')
                                                                $period_cond
                                                                $condition
                                                                AND ectc.end_date_effective IS NULL
                                                                AND ectc.item_part = 'Indirect'
                                                                AND ectc.head_operator = 'Addition'
                                                                $monthly_components_cond
                                                                GROUP BY ectc.salary_head_item_fkey
                                                            ");



        // Variable components
        $arr_variables = $this->EmpCtcTransaction->query("
                                                            SELECT
                                                                ectc.salary_head_item_fkey,
                                                                MAX(ectc.head_operator) AS head_operator,
                                                                MAX(ectc.head_type) AS head_type,
                                                                MAX(ectc.item_part) AS item_part,
                                                                MAX(ectc.salary_head_item_desc) AS salary_head_item_desc,
                                                                SUM(ectc.salary_amount) AS total_salary_amount
                                                            FROM emp_salary_slip ectc
                                                            INNER JOIN payroll_master pm
                                                                ON pm.payroll_master_pkey = ectc.payroll_master_fkey
                                                            LEFT JOIN emp_details ed ON ed.emp_pkey = pm.emp_fkey
                                                            
                                                            WHERE ROUND(ectc.salary_amount) != 0
                                                            AND pm.action IN ('Approved','Processed')
                                                            $period_cond
                                                            $condition
                                                            AND ectc.end_date_effective IS NULL
                                                            AND ectc.head_operator = 'Addition'
                                                            AND ectc.item_part = 'Direct'
                                                            $variable_components_cond
                                                            GROUP BY ectc.salary_head_item_fkey
                                                        ");


        // Net salary
        $arr_net_sal = $this->EmpCtcTransaction->query("
                                                            SELECT
                                                                SUM(
                                                                    CASE
                                                                        WHEN ectc.head_operator = 'Addition'
                                                                            THEN ectc.salary_amount
                                                                        WHEN ectc.head_operator = 'Deduction'
                                                                            THEN -ABS(ectc.salary_amount)
                                                                        ELSE 0
                                                                    END
                                                                ) AS net_salary_amount
                                                            FROM emp_salary_slip ectc
                                                            INNER JOIN payroll_master pm
                                                                ON pm.payroll_master_pkey = ectc.payroll_master_fkey
                                                            LEFT JOIN emp_details ed ON ed.emp_pkey = pm.emp_fkey
                                                            
                                                            WHERE ROUND(ectc.salary_amount) != 0
                                                            AND pm.action IN ('Approved','Processed')
                                                            $period_cond
                                                            $condition
                                                            AND ectc.end_date_effective IS NULL
                                                            AND ectc.item_part = 'Direct';
                                                        ");

        $net_sal = isset($arr_net_sal[0][0]['net_salary_amount'])? $arr_net_sal[0][0]['net_salary_amount']: 0;

        // Deduction components
        $arr_deductions = $this->EmpCtcTransaction->query("
                                                            SELECT
                                                                ectc.salary_head_item_fkey,
                                                                MAX(ectc.head_operator) AS head_operator,
                                                                MAX(ectc.head_type) AS head_type,
                                                                MAX(ectc.item_part) AS item_part,
                                                                MAX(ectc.salary_head_item_desc) AS salary_head_item_desc,
                                                                SUM(ABS(ectc.salary_amount)) AS total_salary_amount
                                                            FROM emp_salary_slip ectc
                                                            INNER JOIN payroll_master pm
                                                                ON pm.payroll_master_pkey = ectc.payroll_master_fkey
                                                            LEFT JOIN emp_details ed ON ed.emp_pkey = pm.emp_fkey
                                                            
                                                            LEFT JOIN salary_head_items shi ON (shi.salary_head_item_pkey = ectc.salary_head_item_fkey AND shi.status=1)
                                                            WHERE ROUND(ectc.salary_amount) != 0
                                                            AND pm.action IN ('Approved','Processed')
                                                            $period_cond
                                                            $condition
                                                            AND ectc.end_date_effective IS NULL
                                                            AND ectc.head_operator = 'Deduction'
                                                            AND ectc.item_part = 'Direct'
                                                            AND NOT EXISTS (
                                                                SELECT 1
                                                                FROM tax_salary_components tsc
                                                                WHERE tsc.salary_head_item_fkey = ectc.salary_head_item_fkey
                                                                AND (
                                                                        tsc.tax_salary_components_name LIKE '%ESI%'
                                                                    OR tsc.tax_salary_components_name LIKE '%EPF%'
                                                                    OR tsc.tax_salary_components_name LIKE '%WWW%'
                                                                )
                                                                AND tsc.status = 1
                                                            )

                                                            AND NOT EXISTS (
                                                                SELECT 1
                                                                FROM salary_head_items shi
                                                                WHERE shi.salary_head_item_pkey = ectc.salary_head_item_fkey
                                                                AND shi.head_fkey IN (4,5)
                                                                AND shi.item_type = 'Fixed'
                                                                AND shi.status = 1
                                                            )

                                                            GROUP BY ectc.salary_head_item_fkey, salary_head_item_desc
                                                        ");

        // EPF components
        $arr_epf = $this->EmpCtcTransaction->query("
                                                            SELECT
                                                                SUM( ABS(ectc.salary_amount)) AS total_salary_amount
                                                            FROM emp_salary_slip ectc
                                                            INNER JOIN payroll_master pm
                                                                ON pm.payroll_master_pkey = ectc.payroll_master_fkey
                                                            LEFT JOIN emp_details ed ON ed.emp_pkey = pm.emp_fkey
                                                            AND pm.action IN ('Approved','Processed')
                                                            
                                                            WHERE ROUND(ectc.salary_amount) != 0
                                                            AND pm.action IN ('Approved','Processed')
                                                            $period_cond
                                                            $condition
                                                            AND ectc.end_date_effective IS NULL
                                                            AND ectc.salary_head_item_fkey IN (SELECT salary_head_item_Fkey FROM tax_salary_components WHERE tax_salary_components_name LIKE '%EPF%' AND status = 1);
                                                        ");
        $epf = isset($arr_epf[0][0]['total_salary_amount'])? $arr_epf[0][0]['total_salary_amount']:0;
        
        // ESI components
        $arr_esi = $this->EmpCtcTransaction->query("
                                                            SELECT
                                                                SUM( ABS(ectc.salary_amount)) AS total_salary_amount
                                                            FROM emp_salary_slip ectc
                                                            INNER JOIN payroll_master pm
                                                                ON pm.payroll_master_pkey = ectc.payroll_master_fkey
                                                            LEFT JOIN emp_details ed ON ed.emp_pkey = pm.emp_fkey
                                                            
                                                            WHERE ROUND(ectc.salary_amount) != 0
                                                            AND pm.action IN ('Approved','Processed')
                                                            $period_cond
                                                            $condition
                                                            AND ectc.end_date_effective IS NULL
                                                            AND ectc.salary_head_item_fkey IN (SELECT salary_head_item_Fkey FROM tax_salary_components WHERE tax_salary_components_name LIKE '%ESI%' AND status = 1);
                                                        ");
        $esi = isset($arr_esi[0][0]['total_salary_amount'])? $arr_esi[0][0]['total_salary_amount']:0;

        // WWF components
        $arr_www = $this->EmpCtcTransaction->query("
                                                            SELECT
                                                                SUM( ABS(ectc.salary_amount)) AS total_salary_amount
                                                            FROM emp_salary_slip ectc
                                                            INNER JOIN payroll_master pm
                                                                ON pm.payroll_master_pkey = ectc.payroll_master_fkey
                                                            LEFT JOIN emp_details ed ON ed.emp_pkey = pm.emp_fkey
                                                            LEFT JOIN salary_head_items shi ON shi.salary_head_item_pkey = ectc.salary_head_item_fkey
                                                            WHERE ROUND(ectc.salary_amount) != 0
                                                            AND pm.action IN ('Approved','Processed')
                                                            $period_cond
                                                            $condition
                                                            AND ectc.end_date_effective IS NULL
                                                            -- AND ectc.salary_head_item_fkey IN (SELECT salary_head_item_Fkey FROM tax_salary_components WHERE tax_salary_components_name LIKE '%WWW%' AND status = 1)
                                                            AND shi.head_fkey IN (4, 5) AND shi.item_type = 'Fixed'
                            
                                                        ");
        $wwf = isset($arr_www[0][0]['total_salary_amount'])? $arr_www[0][0]['total_salary_amount']:0;

        // Settlement
        $arr_settle = $this->EmpCtcTransaction->query(" select sum(salary_amount) from emp_settle_slip as ectc  
                left join emp_details as ed on (ed.emp_pkey = ectc.emp_fkey) 
                left join termination as termination on (termination.emp_fkey = ed.emp_pkey and termination.status=1) 
                $period_join_condtion_settlement
                where ectc.status='Y' and ectc.approved = 'Y' and ectc.type!='SALARY' 
                $period_condtion_settlement
                ");

        $settle = isset($arr_settle['0']['0']['sum(salary_amount)']) ? $arr_settle['0']['0']['sum(salary_amount)'] : 0;
       


        $arr_left = array();
        $arr_right = array();
        $gross = 0;
        foreach($arr_monthly_components as $components){
           $arr_left[] = array(
            'salary_head_item_fkey' => $components['ectc']['salary_head_item_fkey'],
            'head_operator' => $components[0]['head_operator'],
            'head_type' => $components[0]['head_type'],
            'item_part' => $components[0]['item_part'],
            'salary_head_item_desc' => $components[0]['salary_head_item_desc'],
            'salary_amount_l' => $components[0]['total_salary_amount'],
            'salary_amount_r' => ''
           );

           $gross += isset($components[0]['total_salary_amount'])? $components[0]['total_salary_amount']:0;
        }

        if($gross != 0)
        $arr_left[] = array(
            'salary_head_item_desc' => 'Gross Salary',
            'salary_amount_l' => '',
            'salary_amount_r' => $gross,
            'bold' => true
        );

        foreach($arr_indirect_contribution as $components){
           $arr_left[] = array(
            'salary_head_item_fkey' => $components['ectc']['salary_head_item_fkey'],
            'head_operator' => $components[0]['head_operator'],
            'head_type' => $components[0]['head_type'],
            'item_part' => $components[0]['item_part'],
            'salary_head_item_desc' => $components[0]['salary_head_item_desc'],
            'salary_amount_l' => '',
            'salary_amount_r' => $components[0]['total_salary_amount'],
            'bold' => true
           );
        }
        
        if(count($arr_left) > 0)
        $arr_left[] = array(
            'salary_head_item_desc' => '',
            'salary_amount_l' => '',
            'salary_amount_r' => '',
        );

        foreach($arr_variables as $components){
           $arr_left[] = array(
            'salary_head_item_fkey' => $components['ectc']['salary_head_item_fkey'],
            'head_operator' => $components[0]['head_operator'],
            'head_type' => $components[0]['head_type'],
            'item_part' => $components[0]['item_part'],
            'salary_head_item_desc' => $components[0]['salary_head_item_desc'],
            'salary_amount_l' => '',
            'salary_amount_r' => $components[0]['total_salary_amount'],
           );
        }

        if($settle != 0){
            $arr_left[] = array(
                'salary_head_item_desc' => 'Settlement',
                'salary_amount_l' => '',
                'salary_amount_r' => abs($settle),
            );

            $arr_right[] = array(
                'salary_head_item_desc' => 'Settlement',
                'salary_amount_l' => '',
                'salary_amount_r' => abs($settle),
            );
        }

        if($net_sal != 0)
        $arr_right[] = array(
            'salary_head_item_desc' => 'Bank-Salary Payable',
            'salary_amount_l' => '',
            'salary_amount_r' => $net_sal,
        );

        foreach($arr_deductions as $components){
           $arr_right[] = array(
            'salary_head_item_fkey' => $components['ectc']['salary_head_item_fkey'],
            'head_operator' => $components[0]['head_operator'],
            'head_type' => $components[0]['head_type'],
            'item_part' => $components[0]['item_part'],
            'salary_head_item_desc' => $components[0]['salary_head_item_desc'],
            'salary_amount_l' => '',
            'salary_amount_r' => $components[0]['total_salary_amount']
           );
        }

        if($epf != 0)
        $arr_right[] = array(
            'salary_head_item_desc' => 'EPF Payable',
            'salary_amount_l' => '',
            'salary_amount_r' => $epf,
        );

        if($esi != 0)
        $arr_right[] = array(
            'salary_head_item_desc' => 'ESI Payable',
            'salary_amount_l' => '',
            'salary_amount_r' => $esi,
        );

        if($wwf != 0)
        $arr_right[] = array(
            'salary_head_item_desc' => 'WWF/LWF Payable',
            'salary_amount_l' => '',
            'salary_amount_r' => $wwf,
        );

                // Edited by Akshay on 26-5-2026
        $left_total = 0;
        $right_total = 0;

        /* LEFT TOTAL */
        foreach ($arr_left as $row) {
            $left_total += isset($row['salary_amount_r']) && $row['salary_amount_r'] !== ''
                ? (float)$row['salary_amount_r']
                : 0;
        }

        /* RIGHT TOTAL */
        foreach ($arr_right as $row) {
            $right_total += isset($row['salary_amount_r']) && $row['salary_amount_r'] !== ''
                ? (float)abs($row['salary_amount_r'])
                : 0;
        }

        /* DIFFERENCE */
        $balance_amount = $left_total - $right_total;

        if($balance_amount > 0){
          $arr_right[] = array(
            'salary_head_item_desc' => 'Other Components',
            'salary_amount_l' => '',
            'salary_amount_r' => $balance_amount,
        );
        }elseif($balance_amount < 0){
          $arr_left[] = array(
            'salary_head_item_desc' => 'Other Components',
            'salary_amount_l' => '',
            'salary_amount_r' => $balance_amount,
        );
        }
        // End

        $this->set('arr_left', $arr_left);
        $this->set('arr_right', $arr_right);
        $maxCount = max(
            count($arr_left),
            count($arr_right)
        );
        $this->set('maxCount', $maxCount);
        
        // debug($arr_salary_for_template);exit;
        $this->set('arr_salary_for_template', $arr_salary_for_template);
        $employee_attendance = array();
        if (!empty($arr_empleaverequests)) {
            foreach ($arr_empleaverequests as $val) {
                $emp = $val['ectc']['head_operator'];
                $emppk = $val['ectc']['head_type'];
                $itempart = $val['ectc']['item_part'];
                $employee_attendance[$emppk][$emp][$itempart][] = $val;
            }
        }
        $this->set('employee_attendance', $employee_attendance);
        $cr = $arr_form_data['select-criteria1'];
        $this->set('cr', $cr);

        $this->CompanyContactInfo->useDbConfig = $this->Session->read('ds');
        $user_name = $this->Session->read('user_name');
        $this->set('user_name', $user_name);
        $arr_comp_contact_info = $this->CompanyContactInfo->find('first');
        $this->set('arr_comp_contact_info', $arr_comp_contact_info);

        $f = date('Y-m', strtotime($arr_form_data['reportfrom']));
        $time = strtotime($f);
        $month = date("m", $time);
        $mname = date('F', mktime(0, 0, 0, $month, 10));
        $month1 =  $month . '-01';
        $year = date("Y", $time);

        $this->set('mname1', $mname);
        $this->set('y1', $year);
        $this->set('month2', $month);
        $this->set('month1', $month1);

        // Edited by Akshay on 11-2-2026
        $baseUrl = 'http://' . $_SERVER['HTTP_HOST'] . $this->webroot;
        $logoFile = $arr_comp_contact_info['CompanyContactInfo']['logo'];
        $defaultLogo = 'files/companylogos/rizo_logo.png';
        if (!empty($logoFile) && file_exists(WWW_ROOT . $logoFile)) {
            $logoUrl = $baseUrl . $logoFile;
        } else {
            $logoUrl = $baseUrl . $defaultLogo;
        }
        $this->set('finalLogoPath', $logoUrl);
        // End

        switch ($mode) {
            case 'pdf':

                $this->set('mode', 'pdf');
                $view = new View($this, false);
                $view_output = $view->render('account');
                App::import('Vendor', 'HTML2PDF', array('file' => 'html2pdf_v4.03' . DS . 'html2pdf.class.php'));

                $html2pdf = new HTML2PDF('P', 'A4', 'fr');
                $html2pdf->pdf->SetDisplayMode('fullpage');
                $html2pdf->writeHTML($view_output);
                $html2pdf->Output('SalaryAccount_' . $report_from . (isset($report_to)? '-'.$report_to:''). '.pdf', 'D');
                $this->render('account');

                break;
            default:
                $this->set('mode', '');
                $this->render('account');
                break;
        }
    }
