                                            $objPHPExcel->getActiveSheet()->getStyleByColumnAndRow(2, $rowcount)->getFont()->setBold(true);
                                            $pos = $rowcount;
                                            $objPHPExcel->getActiveSheet()->getStyle('A' . $start . ':D' . $pos)->applyFromArray($BStyle);
                                            $start = 0;
                                            $pos = 0;
